-- Run after the migration in a transaction. Every row and auth test identity is rolled back.
insert into auth.users(id,email,raw_user_meta_data) values ('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1','atlas-regression-a@example.invalid','{"display_name":"Atlas regression A"}'),('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2','atlas-regression-b@example.invalid','{"display_name":"Atlas regression B"}'),('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3','atlas-regression-c@example.invalid','{"display_name":"Atlas regression C"}');
set local role authenticated;
select set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',true);
do $test$
declare packet jsonb := '{"id":"synthetic-survey","namespace":"simulation","title":"A journey through the unknown","synthetic":true,"sources":[{"id":"fixture","title":"Synthetic engine fixture","uri":"urn:arcanea-atlas:synthetic:v1","sha256":"ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff","locator":"fixtures.ts · reproducible test scenario, not a manuscript","synthetic":true,"revealChapter":0,"audience":"reader"}],"entities":[{"id":"basin","namespace":"simulation","kind":"location","name":"Survey basin","summary":"The starting point of the synthetic journey.","coordinate":{"system":"local","frame":"synthetic-survey","x":235,"y":405,"z":0,"unit":"m"},"parentId":null,"sourceIds":["fixture"],"status":"provisional","revealChapter":0,"audience":"reader"},{"id":"ridge","namespace":"simulation","kind":"location","name":"Ridge station","summary":"An observation point in a generated test landscape.","coordinate":{"system":"local","frame":"synthetic-survey","x":465,"y":270,"z":0,"unit":"m"},"parentId":null,"sourceIds":["fixture"],"status":"provisional","revealChapter":0,"audience":"reader"},{"id":"crossing","namespace":"simulation","kind":"location","name":"Eastern crossing","summary":"Two witnesses disagree about the crossing. Both reports remain visible.","coordinate":{"system":"local","frame":"synthetic-survey","x":690,"y":360,"z":0,"unit":"m"},"parentId":null,"sourceIds":["fixture"],"status":"provisional","revealChapter":0,"audience":"reader"},{"id":"exit","namespace":"simulation","kind":"location","name":"Far station","summary":"A destination revealed in synthetic chapter four.","coordinate":{"system":"local","frame":"synthetic-survey","x":820,"y":170,"z":0,"unit":"m"},"parentId":null,"sourceIds":["fixture"],"status":"provisional","revealChapter":0,"audience":"reader"},{"id":"portal","namespace":"simulation","kind":"portal","name":"Test portal","summary":"A synthetic spatial discontinuity; not an approved Arcanea portal.","coordinate":{"system":"local","frame":"synthetic-survey","x":700,"y":325,"z":0,"unit":"m"},"parentId":null,"sourceIds":["fixture"],"status":"provisional","revealChapter":0,"audience":"reader"},{"id":"witness-a","namespace":"simulation","kind":"character","name":"Witness A","summary":"Synthetic observer with an explicitly bounded view.","coordinate":null,"parentId":null,"sourceIds":["fixture"],"status":"provisional","revealChapter":0,"audience":"reader"},{"id":"witness-b","namespace":"simulation","kind":"character","name":"Witness B","summary":"An independent synthetic observer.","coordinate":null,"parentId":null,"sourceIds":["fixture"],"status":"provisional","revealChapter":0,"audience":"reader"}],"branches":[{"id":"main","name":"Original path","parentId":null,"forkAt":null,"revealChapter":0,"audience":"reader"},{"id":"alternate","name":"Alternate crossing","parentId":"main","forkAt":50,"revealChapter":0,"audience":"reader"},{"id":"hidden","name":"BRANCH_CANARY","parentId":"main","forkAt":50,"revealChapter":5,"audience":"author"}],"records":[{"id":"arrival","logicalId":"arrival","revision":1,"branchId":"main","validFrom":0,"validTo":null,"recordedFrom":"2026-11-01T00:00:00Z","recordedTo":null,"revealChapter":1,"chapterTitle":"Synthetic chapter 1","chapterHref":null,"title":"The journey begins","detail":"Witness A arrives in the survey basin. Only the first location is known.","audience":"reader","knownBy":["witness-a"],"sourceIds":["fixture"],"status":"provisional","fact":{"kind":"position","entityId":"witness-a","locationId":"basin"}}]}'::jsonb; wid uuid; proposed jsonb; result jsonb; denied boolean; realid uuid;
begin
 denied:=false; begin perform public.atlas_create_world('{}'::jsonb,null); exception when others then denied:=true; end; assert denied,'malformed packet admitted';
 wid:=public.atlas_create_world(packet,null);
 perform public.atlas_grant_view(wid,'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2','reader',null,1);
 perform set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2',true);
 result:=public.atlas_world_context(wid,5,'main',100,clock_timestamp());
 assert jsonb_array_length(result->'document'->'records')=0,'provisional records leaked';
 assert position('BRANCH_CANARY' in result::text)=0,'branch metadata leaked';
 denied:=false;begin perform public.atlas_propose(wid,packet->'records'->0,1);exception when insufficient_privilege then denied:=true;end;assert denied,'reader proposed author content';
 perform set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',true);
 proposed:=public.atlas_propose(wid,packet->'records'->0,1);
 assert jsonb_array_length(public.atlas_pending(wid)->0->'entitySnapshot')=2,'approval omits referenced entities';
 result:=public.atlas_review(wid,(proposed->>'id')::uuid,proposed->>'contentHash',1,'approved');
 assert result->>'status'='approved','approval failed';
 result:=public.atlas_world_context(wid,5,'main',100,clock_timestamp());
 assert jsonb_array_length(result->'document'->'records')=1,'current revision not reconstructed';
 assert result->'document'->'records'->0->>'recordedFrom' ~ 'Z$','timestamp not canonical UTC';
 denied:=false;begin perform public.atlas_review(wid,(proposed->>'id')::uuid,proposed->>'contentHash',1,'approved');exception when serialization_failure then denied:=true;end;assert denied,'replayed approval admitted';
 perform set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2',true);
 result:=public.atlas_world_context(wid,5,'main',100,clock_timestamp());
 assert jsonb_array_length(result->'document'->'records')=1,'approved imported record invisible';
 assert jsonb_array_length(result->'document'->'entities')=2,'approved entity admission failed';
 perform set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',true);
 proposed:=public.atlas_propose(wid,(packet->'records'->0)||jsonb_build_object('branchId','alternate','validFrom',75),2);
 perform public.atlas_review(wid,(proposed->>'id')::uuid,proposed->>'contentHash',2,'approved');
 result:=public.atlas_world_context(wid,5,'main',100,clock_timestamp());
 assert jsonb_array_length(result->'document'->'records')=1,'alternate approval removed main history';
 assert result->'document'->'records'->0->>'branchId'='main','main branch replaced';
 perform set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa2',true);
 result:=public.atlas_world_context(wid,1,'alternate',10,clock_timestamp());
 assert jsonb_array_length(result->'document'->'records')=1,'future child override erased common past';
 perform set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa3',true);
 denied:=false;begin perform public.atlas_world_context(wid,5,'main',100,clock_timestamp());exception when insufficient_privilege then denied:=true;end;assert denied,'cross-tenant read admitted';
 perform set_config('request.jwt.claim.sub','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaa1',true);
 packet:=jsonb_set(jsonb_set(jsonb_set(packet,'{namespace}','"starlight"'),'{records}','[]'),'{entities}',jsonb_build_array((packet->'entities'->0)||jsonb_build_object('namespace','starlight','coordinate',null)));
 realid:=public.atlas_create_world(packet,null);
 perform public.atlas_set_self_location(realid,packet->'entities'->0->>'id',0,0,'coarse',now()+interval '1 hour');
 assert jsonb_array_length(public.atlas_nearby(realid,0,0,100))=1,'PostGIS consented query failed';
 perform public.atlas_revoke_self_location(realid,packet->'entities'->0->>'id');
 assert jsonb_array_length(public.atlas_nearby(realid,0,0,100))=0,'revoked location leaked';
end $test$;
reset role;
select 'passed' as atlas_database_regressions;
